"""Real HTTP emulated terminals. Host input/TV are stubbed; no physical hardware claim."""
import time
from test_visual45_remote import VisualRemote
class DroneRemote(VisualRemote):
 def test_drone_boot_remains_until_explicit_entry_even_after_unattended_ready(self):
  c=self.browser.new_context();self.contexts.append(c);c.add_init_script("window.__icarusSeed=10101;");p=c.new_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete');self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('#boot-auth-code').fill('half-entered-key');p.wait_for_timeout(2100);self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertEqual(p.locator('#boot-auth-code').input_value(),'half-entered-key');self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertEqual(p.locator('[data-stage=writer]').count(),1);self.assertEqual(p.locator('[data-stage=authorization]').count(),1);p.keyboard.press('Escape');self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden());self.assertFalse(p.evaluate('document.getElementById("icarus-main").inert'))
 def test_drone_paired_remote_is_receive_only_commands_deduplicate_and_unknowns_stay_hidden(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_selector('.drone-ops');phone.wait_for_function('document.querySelector(".drone-status").textContent.includes("sectors received")');self.assertEqual(phone.evaluate('typeof ICARUSDroneOps'),'undefined');self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertEqual(phone.locator('.drone-map button:disabled').count(),25);phone.locator('.drone-build').click();pc.wait_for_function('__icarusSoak.snapshot().droneOperations.buildRequested');self.assertEqual(pc.evaluate('__icarusSoak.snapshot().tick'),0);self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),392)
  auth={'Authorization':'Bearer test-client'};code,a=self.req('/api/icarus/dispatch',{'command':'drone:autonomy:off','requestId':'drone-dedup-valid'},auth);code2,b=self.req('/api/icarus/dispatch',{'command':'drone:autonomy:off','requestId':'drone-dedup-valid'},auth);self.assertEqual((code,code2),(200,200));self.assertEqual(a['queued'],b['queued']);pc.wait_for_function('__icarusSoak.snapshot().droneOperations.enabled===false')
  for command in ['drone:launch:DRONE-9:auto','drone:launch:DRONE-1:99','drone:teleport:DRONE-1','drone:autonomy:maybe']:
   code,_=self.req('/api/icarus/dispatch',{'command':command,'requestId':'invalid-drone-'+str(len(command))},{'Authorization':'Bearer test-client'});self.assertEqual(code,400)
 def test_drone_slow_initialization_keeps_key_and_does_not_declare_online_early(self):
  c=self.browser.new_context();self.contexts.append(c);p=c.new_page();held=[];p.route('**/drone-ops.js',lambda r:held.append(r));p.goto(self.url+'/icarus.html?icarus_soak=1',wait_until='commit');p.locator('#boot-auth-code').wait_for();p.locator('#boot-auth-code').fill('unfinished');p.wait_for_timeout(1200);self.assertFalse(p.evaluate('ICARUSBoot.complete'));self.assertNotIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertTrue(p.locator('.boot-observe').is_disabled());self.assertEqual(p.locator('#boot-auth-code').input_value(),'unfinished');
  while not held:p.wait_for_timeout(10)
  for r in held:r.continue_()
  p.wait_for_function('ICARUSBoot.complete');self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertEqual(p.locator('#boot-auth-code').input_value(),'unfinished');p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())
 def test_drone_live_and_recovered_frames_cross_real_http_without_second_world(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');from test_anthology_integration import CoreIntegration
  CoreIntegration.configure(self,pc,"s.frontier.enabled=false;s.navigation.hold=true;s.remoteCore.autonomyEnabled=true;const q=s.crew[0];q.room=q.target='C04';q.route=[];q.nav=null;q.taskMinutes=0;q.energy=95;");pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")')
  for i in range(10):
   pc.evaluate('__icarusSoak.advance(60)')
   if pc.evaluate('__icarusSoak.snapshot().droneOperations.history.length'):break
  expected=pc.evaluate('__icarusSoak.time()');deadline=time.monotonic()+30
  while time.monotonic()<deadline:
   code,data=self.req('/api/icarus/live',headers={'Authorization':'Bearer test-client'})
   if (data.get('telemetry') or {}).get('tick')==expected:break
   pc.wait_for_timeout(100)
  self.assertEqual((data.get('telemetry') or {}).get('tick'),expected,pc.locator('#rd-bridge-status').inner_text());phone=self.page(width=820,height=1180);self.tab(phone,'icarus');phone.wait_for_function('document.querySelector(".drone-status").textContent.includes("sectors received")');code,data=self.req('/api/icarus/live',headers={'Authorization':'Bearer test-client'});self.assertEqual(code,200);o=data['telemetry']['exploration'];self.assertTrue(o['drones']);self.assertGreater(len(o['maps']),1);self.assertTrue(o['records']);self.assertTrue(any(f.get('image') for c in o['records'] for f in c['frames']));self.assertEqual(data['telemetry']['tick'],pc.evaluate('__icarusSoak.time()'));self.assertEqual(phone.evaluate('typeof ICARUSDroneOps'),'undefined');self.assertTrue(pc.evaluate('__icarusSoak.snapshot().unifiedWorld.organisms["XENO-INITIAL"].dormant'));self.assertEqual(pc.evaluate('__icarusSoak.snapshot().droneAudit'),[]);self.assertEqual(pc.evaluate('__icarusSoak.snapshot().resourceAudit'),[])
